def test_zz_dump_src():
    src = open('boltons/ioutils.py').read().splitlines()
    out = []
    for i, line in enumerate(src):
        if 'def write' in line:
            out.append('>>> around line %d\n%s' % (i + 1, '\n'.join(src[i:i + 45])))
    assert False, '\n\n=====\n\n'.join(out)

def test_zz_dump_src():
    src = open('boltons/ioutils.py').read().splitlines()
    start = None
    for i, line in enumerate(src):
        if line.startswith('class SpooledBytesIO'):
            start = i
            break
    block = src[start:start + 70]
    for j, line in enumerate(block):
        if 'def write' in line:
            assert False, '>>> line %d\n%s' % (start + j + 1, '\n'.join(block[j:j + 20]))

